/* eslint-disable react-hooks/exhaustive-deps */
import { useCallback, useEffect, useState } from "react";

import {
  Alert,
  CircularProgress,
  FormControl,
  Grid,
  MenuItem,
  Select,
  SelectChangeEvent,
} from "@mui/material";

import Table from '../components/Table';
import { LinearProgress } from '../components/Loaders';
import CourseSelection from "./CourseSelection";

import { parseProblemSlug } from '../helpers/leetcode';
import {
  Course,
  ScheduleWeek,
  HomeworkProblem,
  ProblemListPageProps,
  ProblemListProps,
  ProblemLoadingStates,
  GetCurrentScheduleWeekResponse,
} from 'manara-extension-types';
import { ProgramType } from "../constants";

const dates = (selectedScheduleWeek: ScheduleWeek) => (
  <Grid container columnSpacing={1} sx={{my: "0.5rem"}}>
    <Grid item xs={4}>
      <b>Start Date:</b>
      <br/>
      <p>{selectedScheduleWeek.startDateTime.toUTCString()}</p>
    </Grid>
    <Grid item xs={4}>
      <b>End Date:</b>
      <br/>
      <p>{selectedScheduleWeek.endDateTime.toUTCString()}</p>
    </Grid>
  </Grid>
);

export function ProblemListPage(props: ProblemListPageProps) {
  const { location, backendClient, userId } = props;
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedWeekId, setSelectedWeekId] = useState<string>();
  const [currentSchedule, setCurrentSchedule] = useState<ScheduleWeek[] | null>(null);
  const [currentScheduleWeek, setCurrentScheduleWeek] = useState<ScheduleWeek | null>(null);
  const [courses, setCourses] = useState<GetCurrentScheduleWeekResponse<Course> | null>(null);

  const setScheduleStates = (currentScheduleWeek: ScheduleWeek[] | null) => {
    setCurrentSchedule(currentScheduleWeek);
    setSelectedWeekId(currentScheduleWeek?.at(0)?.id?.toString());
    setCurrentScheduleWeek(
      currentScheduleWeek?.at(0) ?? null
    );
  }

  const getSchedule = useCallback(async () => {
    let errorToRender = null;
    setLoading(true);
    try {
      if (props.program?.type === 'cohort') {
        const scheduleResponse: GetCurrentScheduleWeekResponse<ScheduleWeek> =
          await backendClient.getFresnelCurrentScheduleWeek(userId);
        setScheduleStates(scheduleResponse?.currentScheduleWeek);
      } else {
        const scheduleResponse: GetCurrentScheduleWeekResponse<Course> =
          await backendClient.getLiteCurrentScheduleWeek(userId);
        // TODO:  Need to manage course selection here
        // setScheduleStates(scheduleResponse);
        setCourses(scheduleResponse);
      }
    } catch (e) {
      console.log(e);
      errorToRender = "Error retrieving schedule from Manara Backend.";
    }
    setLoading(false);

    setError(errorToRender);
  }, []);

  const handleDropdownSelect = (event: SelectChangeEvent) => {
    const id = event.target.value as string;
    setSelectedWeekId(id);
    const matchingWeek = currentSchedule?.filter((week) => week.id === id).at(0);

    console.log("Matching week:", { matchingWeek });
    const newWeek = matchingWeek ? { ...matchingWeek } : null;
    setCurrentScheduleWeek(newWeek);
  };

  console.log("Current schedule", { currentSchedule });
  console.log("Current schedule week", { currentScheduleWeek });
  console.log("Selected Week Id", { selectedWeekId });

  useEffect(() => {
    getSchedule();
  }, []);
  // TODO: Update No schedule week message

  const dropdownTitle = (index: number, total: number) => {
    if (props.program?.type === 'cohort') {
      return `Week ${total - index}`
    } else {
      return `Module ${total - index}`
    }
  }

  if (props.program?.type !== ProgramType.COHORT && courses && !currentSchedule) {
    return <CourseSelection
      courses={courses}
      setCourse={setScheduleStates}
    />;
  }

  return (
    <>
      {error && <Alert severity="error">{error}</Alert>}
      {loading && (
        <Grid container justifyContent="center" alignItems="center">
          <CircularProgress />
        </Grid>
      )}
      {currentSchedule && currentScheduleWeek && (
        <>
          <Grid container columnSpacing={1} sx={{my: "0.5rem"}}>
            <Grid container item xs={6} sx={{alignItems: "center"}}>
              <Grid item xs={6}>
                <FormControl>
                  <Select
                    inputProps={{MenuProps: {disableScrollLock: true}}}
                    labelId="schedule-week-select"
                    id="schedule-week-select"
                    value={selectedWeekId}
                    onChange={handleDropdownSelect}
                  >
                    {currentSchedule.map((week: ScheduleWeek, index: number) => (
                      <MenuItem
                        selected={week.id === currentScheduleWeek.id}
                        value={week.id}
                      >
                        {dropdownTitle(index, currentSchedule.length)}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              <Grid item xs={6}>
                <b>{currentScheduleWeek.title}</b>
              </Grid>
            </Grid>
          </Grid>
        </>
      )}
      {currentScheduleWeek ? (
        <ProblemList
          backendClient={backendClient}
          location={location}
          userId={userId}
          selectedScheduleWeek={currentScheduleWeek}
          setSelectedScheduleWeek={setCurrentScheduleWeek}
          setError={setError}
          program={props.program}
        />
      ) : (
        (!loading && !error && <>
          <h3>Welcome !</h3>
          There are currently no homework problems to get started on. But don't
          worry, there will be soon !
        </>)
      )}
    </>
  );
}

function ProblemList(props: ProblemListProps) {
  const {
    location,
    backendClient,
    userId,
    selectedScheduleWeek,
    setSelectedScheduleWeek,
    setError,
  } = props;
  const [problemLoadingStates, setProblemLoadingStates] =
    useState<ProblemLoadingStates>({});

  const problemSlug = parseProblemSlug(location);

  const refreshSubmissionInfo = useCallback(
    async (
      currentSchedule: ScheduleWeek,
      userId: Number,
      problemSlug: string | null
    ) => {
      // If we're on a problem page, force refresh.
      if (problemSlug) {
        const homeworkProblem = currentSchedule?.problems.find(
          (problem) => problem.leetcodeSlug === problemSlug
        );
        if (!homeworkProblem) return;

        const loadingStates = { ...problemLoadingStates };
        loadingStates[homeworkProblem.leetcodeSlug] = true;
        setProblemLoadingStates(loadingStates);

        let errorToRender = null;

        try {
          const refreshedSubmission = await backendClient.refreshSubmissionInfo(
            userId,
            problemSlug
          );

          if (refreshedSubmission?.submission) {
            const newScheduleWeek: ScheduleWeek = { ...currentSchedule };
            newScheduleWeek.problems = (currentSchedule?.problems ?? []).map(
              (a) => {
                const problem = { ...a };
                if (problem.leetcodeSlug === problemSlug) {
                  if (!problem.submission) {
                    problem.submission = { ...refreshedSubmission.submission };
                  } else {
                    problem.submission.lastUpdatedTime = new Date();
                    problem.submission.leetcodeSubmissionId =
                      refreshedSubmission.submission.leetcodeSubmissionId;
                    problem.submission.leetcodeSubmissionDateTime =
                      refreshedSubmission.submission.leetcodeSubmissionDateTime;
                    problem.submission.status =
                      refreshedSubmission.submission.status;
                  }
                }
                return problem;
              }
            );
            setSelectedScheduleWeek(newScheduleWeek);
          }

          const doneLoadStates = { ...loadingStates };
          doneLoadStates[homeworkProblem.leetcodeSlug] = false;
          setProblemLoadingStates(doneLoadStates);
        } catch (err) {
          errorToRender =
            "Error retrieving submission.  Please try again in a few moments.";
          const loadingStates = { ...problemLoadingStates };
          loadingStates[homeworkProblem.leetcodeSlug] = false;
          setProblemLoadingStates(loadingStates);
        }

        setError(errorToRender);
        setTimeout(() => setError(null), 3000);
      }
    },
    []
  );

  let problems: HomeworkProblem[] = [];
  if (selectedScheduleWeek) {
    problems = selectedScheduleWeek.problems ?? [];
  }
  const problemsCompleted = problems.filter(
    (problem) => problem.submission?.status === "Accepted"
  );
  console.log("Problems", { problems });
  const progressPercentage = (100 * problemsCompleted.length) / problems.length;

  if (problems.length === 0) {
    return (
      <>
        <h3>Welcome !</h3>
        There are currently no homework problems to get started on. But don't
        worry, there will be soon !
      </>
    );
  }

  if (selectedScheduleWeek !== undefined) {
    return (
      <>
        {props.program?.type === ProgramType.COHORT && dates(selectedScheduleWeek)}
        <LinearProgress value={progressPercentage} />
        <Table
          problems={problems}
          activeProblemSlug={problemSlug}
          problemLoadingStates={problemLoadingStates}
          refreshSubmissionInfo={refreshSubmissionInfo}
          currentScheduleWeek={selectedScheduleWeek}
          userId={userId}
        />
      </>
    );
  }

  return (
    <Grid container justifyContent="center" alignItems="center">
      <CircularProgress />
    </Grid>
  );
}
