import TableHeader from './Header';
import { DifficultyChip } from '../Chips';

import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell from "@mui/material/TableCell";
import TableContainer from "@mui/material/TableContainer";
import InfoIcon from "@mui/icons-material/Info";
import TableRow from "@mui/material/TableRow";
import Paper from "@mui/material/Paper";
import Tooltip from "@mui/material/Tooltip";
import { Box, CircularProgress, Link, Button } from "@mui/material";

import { EnhancedTableProps } from 'manara-extension-types';

export default function EnhancedTable(props: EnhancedTableProps) {
    const {
        problems,
        activeProblemSlug,
        problemLoadingStates,
        refreshSubmissionInfo,
        currentScheduleWeek,
        userId,
    } = props;

    const openProblem = (problemSlug: string) => {
        chrome.tabs.create({ url: `https://leetcode.com/problems/${problemSlug}` });
    };

    console.log("Table Schedule Week", { currentScheduleWeek });

    return (
        <TableContainer component={Paper}>
            <Table aria-labelledby="tableTitle" sx={{ minWidth: 650 }} size="medium">
                <TableHeader />
                <TableBody>
                    {/* if you don't need to support IE11, you can replace the `stableSort` call with:
                rows.slice().sort(getComparator(order, orderBy)) */}
                    {problems.map((problem, index) => {
                        const labelId = `enhanced-table-checkbox-${index}`;

                        return (
                            <TableRow hover tabIndex={-1} key={problem.title}>
                                <TableCell component="th" id={labelId} scope="row">
                                    <Link
                                        className="problem-title"
                                        onClick={(_e) => openProblem(problem.leetcodeSlug)}
                                    >
                                        {problem.title}
                                    </Link>
                                    {activeProblemSlug &&
                                        activeProblemSlug === problem.leetcodeSlug && (
                                            <>
                                                <span>&nbsp;(Active)&nbsp;</span>
                                                <Tooltip title="We detected that you're currently working on / browsing this problem">
                                                    <InfoIcon fontSize="inherit" />
                                                </Tooltip>
                                            </>
                                        )}
                                </TableCell>
                                <TableCell align="right">
                                    <DifficultyChip difficulty={problem.difficulty} />
                                </TableCell>
                                <TableCell align="right">
                                    <Box display="inline">
                                        {problemLoadingStates[problem.leetcodeSlug] ? (
                                            <CircularProgress size="1.5rem" />
                                        ) : (
                                            <p>{problem.submission?.status ?? "Not Submitted"}</p>
                                        )}
                                    </Box>
                                </TableCell>
                                <TableCell align="right">
                                    <Box display="inline">
                                        <Button
                                          style={{
                                              borderRadius: "45%",
                                              border: "solid lightgray",
                                              color: "text",
                                          }}
                                          variant="outlined"
                                          onClick={() => {
                                              refreshSubmissionInfo(
                                                currentScheduleWeek,
                                                userId,
                                                problem.leetcodeSlug
                                              );
                                          }}
                                        >
                                            Check
                                        </Button>
                                    </Box>
                                </TableCell>
                            </TableRow>
                        );
                    })}
                </TableBody>
            </Table>
        </TableContainer>
    );
}
