/* eslint-disable react-hooks/exhaustive-deps */
import AppContent from './components/AppContent';
import {
  Box,
  Button,
  Grid,
} from "@mui/material";
import CloseIcon from '@mui/icons-material/Close';

import { VERSION } from './constants';

import "./App.css";
import {useState} from "react";
import { ManaraAuthInfo, Program, LeetcodeAuth } from "manara-extension-types";

function App() {
  const [leetcodeAuth, setLeetcodeAuth] = useState<LeetcodeAuth | null>(null);
  const [manaraAuth, setManaraAuth] = useState<ManaraAuthInfo | null>(null);
  const [program, setProgram] = useState<Program | null>(null);
  const [course, setCourse] = useState<string | null>(null);

  return (
    <>
      <Box sx={{ p: 4, flexGrow: 1 }}>
        <Grid container justifyContent="center" spacing={2}>
          <Grid item container xs={12} justifyContent="center" alignContent="center">
            <img src="/images/manara-logo-black-text.svg" alt="Manara logo" />
            {leetcodeAuth && manaraAuth && program && <p>&nbsp;: {program.label}</p>}
            {manaraAuth && manaraAuth.program?.length >= 1 && program && <Button
              onClick={() => {setProgram(null)}}
            >
              <CloseIcon sx={{ position: "fixed", top: "0.5rem", right: "0.5rem", zIndex: 2000, backgroundColor: "lightgray" }}/>
            </Button>}
          </Grid>
          <Grid item xs={12}>
            <AppContent
              manaraAuth={manaraAuth}
              program={program}
              course={course}
              setManaraAuth={setManaraAuth}
              setProgram={setProgram}
              setCourse={setCourse}
              leetcodeAuth={leetcodeAuth}
              setLeetcodeAuth={setLeetcodeAuth}
            />
          </Grid>
        </Grid>
      </Box>
      <div className="version">
      {`v.${VERSION}`}
      </div>
    </>
  );
}

export default App;
