import TableHead from "@mui/material/TableHead";
import TableCell from "@mui/material/TableCell";
import TableRow from "@mui/material/TableRow";

import { HeadCell } from 'manara-extension-types';

export default function Header() {
    const headCells: readonly HeadCell[] = [
        {
            id: "title",
            numeric: false,
            disablePadding: true,
            label: "Title",
        },
        {
            id: "difficulty",
            numeric: false,
            disablePadding: false,
            label: "Difficulty",
        },
        {
            id: "submissionStatus",
            numeric: false,
            disablePadding: false,
            label: "Status",
        },
    ];

    return (
        <TableHead>
            <TableRow>
                {headCells.map((headCell) => (
                    <TableCell
                        key={headCell.id}
                        align={headCell.id === "title" ? "left" : "right"}
                    >
                        {headCell.label}
                    </TableCell>
                ))}
                <TableCell key="refresh"></TableCell>
            </TableRow>
        </TableHead>
    );
}
