import { LeetcodeAuth } from 'manara-extension-types';

export const LEETCODE_SESSION = "LEETCODE_SESSION";
export const LEETCODE_CSRF = "csrftoken";
export const LEETCODE_URL = "https://leetcode.com";

export const checkLeetcodeAuth = async (): Promise<null | LeetcodeAuth> => {
  const csrf = await chrome.cookies.get({
    name: LEETCODE_CSRF,
    url: LEETCODE_URL
  });

  const session = await chrome.cookies.get({
    name: LEETCODE_SESSION,
    url: LEETCODE_URL
  });

  if(!csrf || !session){
    console.log("LEETCODE AUTH RETURNED NULL");
    return null;
  }

  return {
    csrf: csrf.value,
    session: session.value
  }
}

export const parseProblemSlug = (location: Location | null): string | null => {
  // TODO extract constant
  if (location && location.host === "leetcode.com") {
    const tokens = location.href.split("/");
    for (let i = 0; i < tokens.length; i++) {
      // TODO extract constant
      if (tokens[i] === "problems" && i + 1 < tokens.length) {
        return tokens[i + 1];
      }
    }
  }
  return null;
};

export const leetcodeLogout = async (): Promise<null> => {
  await chrome.cookies.remove({
    name: LEETCODE_CSRF,
    url: LEETCODE_URL
  });

  await chrome.cookies.remove({
    name: LEETCODE_SESSION,
    url: LEETCODE_URL
  });

  return null;
}