import axios from "axios";
import {
  GetCurrentScheduleWeekResponse,
  LeetcodeAuth,
  ManaraAuthInfo,
  RefreshSubmissionResponse,
  Course,
  ScheduleWeek,
} from "manara-extension-types";
import { leetcodeLogout } from "../helpers/leetcode";

export class BackendClient {
  accessToken: string | null
  leetcodeAuthInfo: LeetcodeAuth | null
  static readonly baseUrl: string = "https://99y6xsjzk1.execute-api.us-east-2.amazonaws.com/prod";

  constructor() {
    this.leetcodeAuthInfo = null;
    this.accessToken = null;
  }

  private getLeetcodeHeaders() {
    if(!this.leetcodeAuthInfo){
      throw new Error("No Leetcode Auth Info!");
    }
    return {
      'X-Manara-Lc-Csrf': this.leetcodeAuthInfo.csrf,
      'X-Manara-Lc-Session': this.leetcodeAuthInfo.session
    }
  }

  private getAuthorizationHeader() {
    if (!this.accessToken) {
      throw new Error("Not authenticated with Manara Backend!");
    }
    return {
      'Authorization': `Bearer ${this.accessToken}`
    }
  }

  public setAccessToken(accessToken: string){
    this.accessToken = accessToken;
  }

  static async login(email: string, secret: string): Promise<ManaraAuthInfo> {
    const response: Promise<ManaraAuthInfo> = axios.post<ManaraAuthInfo>(
      `${BackendClient.baseUrl}/login`,
      {
        email,
        secret
      },
    ).then((res) => {
      if(!res?.data?.accessToken){
        throw new Error("Unexpected response during Github OAuth with Manara Backend!");
      }
      return res.data;
    })
    .catch((err) => {
      throw new Error("Unable to login");
    });

    return response;
  }

  public setLeetcodeInfo(leetcodeAuthInfo: LeetcodeAuth | null) {
    this.leetcodeAuthInfo = leetcodeAuthInfo;
  }

  public async getFresnelCurrentScheduleWeek(userId: Number): Promise<GetCurrentScheduleWeekResponse<ScheduleWeek>> {
    const scheduleWeekResponse = (await axios.get<GetCurrentScheduleWeekResponse<ScheduleWeek>>(
      `${BackendClient.baseUrl}/programs/cohort/users/${userId}?ts=${Date.now()}`,
      {
        headers: {}
      }
    )).data;

    if (scheduleWeekResponse.currentScheduleWeek) {
      for (let index = 0; index < scheduleWeekResponse.currentScheduleWeek.length; index += 1) {
        const newSchedule = scheduleWeekResponse.currentScheduleWeek[index];
        newSchedule.endDateTime = new Date(newSchedule.endDateTime);
        newSchedule.startDateTime = new Date(newSchedule.startDateTime);
      }
      scheduleWeekResponse.currentScheduleWeek.sort((a, b) =>
        b.startDateTime.getTime() - a.startDateTime.getTime()
      );
    }

    return scheduleWeekResponse;
  }

  public async getLiteCurrentScheduleWeek(userId: Number): Promise<GetCurrentScheduleWeekResponse<Course>> {
    const scheduleWeekResponse = (await axios.get<GetCurrentScheduleWeekResponse<Course>>(
      `${BackendClient.baseUrl}/programs/flex/users/${userId}?ts=${Date.now()}`,
      {
        headers: {}
      }
    )).data;

    if (scheduleWeekResponse.currentScheduleWeek) {
      for (let index = 0; index < scheduleWeekResponse.currentScheduleWeek.length; index += 1) {
        const course = scheduleWeekResponse.currentScheduleWeek[index];
        for (let moduleIndex = 0; moduleIndex < course.modules.length; moduleIndex += 1) {
          const newSchedule = course.modules[moduleIndex];
          newSchedule.endDateTime = new Date(newSchedule.endDateTime);
          newSchedule.startDateTime = new Date(newSchedule.startDateTime);
        }
        course.modules.sort((a, b) =>
          b.startDateTime.getTime() - a.startDateTime.getTime()
        );
      }
    }

    return scheduleWeekResponse;
  }

  public async refreshSubmissionInfo(userId: Number, problemSlug: string): Promise<RefreshSubmissionResponse> {
    if (!this.accessToken) {
      throw new Error("Not authenticated!");
    }
    try {
      return(await axios.post(
        `${BackendClient.baseUrl}/users/${userId}/problems/${problemSlug}/submissions`,
        {},
        {
          headers: {
            ...this.getAuthorizationHeader(),
            ...this.getLeetcodeHeaders()
          }
        }
      )).data;
      
    } catch (error) {
      this.setLeetcodeInfo(null);
      await leetcodeLogout();
      throw new Error("Fetch submissions error!");
    }
  }  
}
