import { Button, Grid } from '@mui/material';
import { ProgramSelectionProps, Program } from "manara-extension-types";
import { ProgramType } from "../constants";

export default function ProgramSelection(props: ProgramSelectionProps) {
  function saveProgram(program: Program) {
    chrome.storage.local.set({ program: program });
    props.setProgram(program);
  }

  const buttons = props.programs.map((program) => (
    <Button
      style={{margin: "1rem"}}
      color="primary"
      variant="contained"
      fullWidth={true}
      onClick={() => saveProgram(program)}
    >
      {(program.type === ProgramType.COHORT) ? 'Manara Cohort' : 'Manara Flexible'}
    </Button>
  ))

  return (
    <div
      style={{
        margin: "2rem 0rem",
        border: "solid 0.1rem lightgrey",
        borderRadius: "10px",
        padding: "1rem",
      }}
    >
        <Grid
          container
          alignItems="center"
          style={{
            padding: "1rem",
            textAlign: "center",
            justifyContent: "center",
          }}
        >
        <h1>
          Select Program
        </h1>
          {buttons}
      </Grid>
    </div>
  );
};
