/* eslint-disable react-hooks/exhaustive-deps */
import { useCallback, useEffect, useMemo, useState } from 'react';

import { ProblemListPage } from "../components/ProblemList";
import Auth, { AuthProcessState } from './Auth';
import ProgramSelection from "./ProgramSelection";

import { checkLeetcodeAuth } from "../helpers/leetcode";
import { BackendClient } from '../services/backend';
import { WindowLocationEvaluatorMessage, WindowLocationEvaluatorResponse, AppContentProps } from 'manara-extension-types';

export default function AppContent(props: AppContentProps) {
  const [location, setLocation] = useState<Location | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [authProcessState, setAuthProcessState] = useState<AuthProcessState | null>(AuthProcessState.NOT_STARTED);
  const [waitingForLogin, setWaitingForLogin] = useState<boolean>(false);
  const [isValidLeetcodeCredentials, setIsValidLeetcodeCredentials] = useState<boolean>(false);

  const checkAuth = useCallback(async () => {
    // Attempt to get leetcode information:
    setAuthProcessState(AuthProcessState.GETTING_LEETCODE);
    props.setLeetcodeAuth(await checkLeetcodeAuth());

    let errorToRender = null;
    
    // Check if we already have Manara Authentication Cached for the User
    setAuthProcessState(AuthProcessState.GETTING_MANARA);
    console.log("Checking local storage for Manara Access Token...");
    const storage = await chrome.storage.local.get(["manaraChrome", "program"]);
    if (storage?.manaraChrome?.accessToken) {
      console.log(`Found Manara Chrome Access Info!`);
      props.setManaraAuth(storage?.manaraChrome);
    } else {
      console.log("No Manara Access Token found!");
    }
    if (props.manaraAuth?.program?.length === 1) {
      props.setProgram(props.manaraAuth.program[0]);
    } else if (storage?.program) {
      props.setProgram(storage.program);
    }

    setAuthProcessState(AuthProcessState.COMPLETE);
    setError(errorToRender);

    // TODO - extract to problem list component
    chrome.tabs &&
      chrome.tabs.query(
        {
          active: true,
          currentWindow: true,
        },
        (tabs) => {
          chrome.tabs.sendMessage(
            tabs[0].id || 0,
            { type: "GET_WINDOW_LOCATION" } as WindowLocationEvaluatorMessage,
            async (response: WindowLocationEvaluatorResponse) => {
              if (!window.chrome.runtime.lastError) {
                if (response?.location) setLocation(response.location);
              }
            }
          );
        }
      );
    }, []);
    
    useEffect(() => {
      checkAuth();
    }, []);

    const backendClient = useMemo(() => {
      const client = new BackendClient();
      if (props.manaraAuth) {
        client.setAccessToken(props.manaraAuth.accessToken);
      }
      if (props.leetcodeAuth) {
        client.setLeetcodeInfo(props.leetcodeAuth);
      }
      return client;
    }, [props.manaraAuth, props.leetcodeAuth]);

  const checkAndValidateLeetcodeCredentials = async () => {
    try {
      console.log('Validating Leetcode credentials...');
      if (props.manaraAuth && props.leetcodeAuth) {
        await backendClient.refreshSubmissionInfo(
          props.manaraAuth.id,
          'check-if-two-string-arrays-are-equivalent'
        );
        setIsValidLeetcodeCredentials(true);
      }
    } catch (error) {
      console.log('Leetcode credentials validation error:', error);
      setError('Failed to validate Leetcode credentials');
      props.setLeetcodeAuth(null);
      setIsValidLeetcodeCredentials(false);
    }
  };
  useEffect(() => {
    checkAndValidateLeetcodeCredentials();
  }, [props.manaraAuth, props.leetcodeAuth]);


  const handleLogin = useCallback(async (email, secret) => {
    try {
      setWaitingForLogin(true);
      setError(null);
      const manaraAuthResponse = await BackendClient.login(email, secret);
      if (manaraAuthResponse) {
        chrome.storage.local.set({
          manaraChrome: manaraAuthResponse,
        });
        props.setManaraAuth(manaraAuthResponse);
      }
    } catch (err) {
      console.log(err);
      setError("Error logging in!");
    }
    setWaitingForLogin(false);
  }, []);

  if (props.manaraAuth && props.leetcodeAuth && isValidLeetcodeCredentials) {
    if (props.program) {
      return <ProblemListPage
        backendClient={backendClient}
        location={location}
        userId={props.manaraAuth.id}
        program={props.program}
      />;
    } else if (props.manaraAuth.program?.length > 0) {
      return (
        <ProgramSelection
          programs={props.manaraAuth.program}
          setProgram={props.setProgram}
        />
      );
    } else {
      return (
        <div>
          You aren't currently enrolled in any Manara programs which use this extension.
        </div>
      );
    }
  }

  return (
    <Auth
      error={error}
      manaraAuth={props.manaraAuth}
      leetcodeAuth={props.leetcodeAuth}
      authProcessState={authProcessState}
      waitingForLogin={waitingForLogin}
      onLogin={handleLogin}
    />
  );
};
