import { ChangeEvent, useState } from 'react';
import { CheckCircle, Dangerous } from "@mui/icons-material";
import { Alert, Button, CircularProgress, Grid, TextField } from '@mui/material';

import { AuthComponentProps } from 'manara-extension-types';

export enum AuthProcessState {
    NOT_STARTED,
    GETTING_LEETCODE,
    GETTING_MANARA,
    COMPLETE,
}

export default function Auth({
    error,
    authProcessState,
    leetcodeAuth,
    manaraAuth,
    waitingForLogin,
    onLogin,
}: AuthComponentProps) {
    const [emailInput, setEmailInput] = useState<string>("");
    const [secretInput, setSecretInput] = useState<string>("");

    const handleEmailChange = (event: ChangeEvent<HTMLInputElement>) => {
        setEmailInput(event.target.value);
    };

    const handleSecretChange = (event: ChangeEvent<HTMLInputElement>) => {
        setSecretInput(event.target.value);
    };

    const isLoadingAuthStatus = (
        authProcessState === AuthProcessState.GETTING_MANARA
        || authProcessState === AuthProcessState.GETTING_LEETCODE
    );
    const notLoggedWithManara = authProcessState === AuthProcessState.COMPLETE && !manaraAuth;
    const notLoggedWithLeetCode = authProcessState === AuthProcessState.COMPLETE && !leetcodeAuth;
    const isAuthenticatingLeetCode = authProcessState === AuthProcessState.GETTING_LEETCODE;

    return (
        <h2>
            {error && <Alert severity="error">{error}</Alert>}

            <div
                style={{
                    border: "solid 0.1rem lightgrey",
                    borderRadius: "10px",
                    padding: "1rem",
                }}
            >
                <div>
                    Leetcode Authentication:{" "}
                    {isAuthenticatingLeetCode ? (
                        <CircularProgress size="0.75rem" />
                    ) : leetcodeAuth ? (
                        <CheckCircle color="success" fontSize="small"></CheckCircle>
                    ) : (
                        <Dangerous color="error" fontSize="small"></Dangerous>
                    )}
                </div>
                <div>
                    {notLoggedWithLeetCode && (
                        <>
                            <br />
                            <Grid container justifyContent="center" alignItems="center">
                                <Button
                                    variant="contained"
                                    onClick={() =>
                                        chrome.tabs.create({
                                            url: `https://leetcode.com/accounts/login/`,
                                        })
                                    }
                                >
                                    Login to LeetCode
                                </Button>
                            </Grid>
                        </>
                    )}
                </div>
            </div>

            <div
                style={{
                    margin: "2rem 0rem",
                    border: "solid 0.1rem lightgrey",
                    borderRadius: "10px",
                    padding: "1rem",
                }}
            >
                <div>
                    Manara Authentication:{" "}
                    {isLoadingAuthStatus ? (
                        <CircularProgress size="0.75rem" />
                    ) : manaraAuth ? (
                        <CheckCircle color="success" fontSize="small"></CheckCircle>
                    ) : (
                        <Dangerous color="error" fontSize="small"></Dangerous>
                    )}
                </div>

                {notLoggedWithManara && (
                    <div>
                        <>
                            <Grid container alignItems="center">
                                <TextField
                                    required
                                    hiddenLabel={false}
                                    id="outlined-required"
                                    label="Email (Required)"
                                    onChange={handleEmailChange}
                                    disabled={waitingForLogin}
                                    margin="normal"
                                />
                                <TextField
                                    required
                                    hiddenLabel={false}
                                    id="outlined-password-input"
                                    label="Secret (Required)"
                                    type="password"
                                    onChange={handleSecretChange}
                                    disabled={waitingForLogin}
                                    margin="normal"
                                />
                            </Grid>
                            <Button
                                color="primary"
                                variant="contained"
                                onClick={() => onLogin(emailInput, secretInput)}
                                disabled={waitingForLogin}
                            >
                                Login
                            </Button>
                            {waitingForLogin && <CircularProgress size="0.75rem" />}
                        </>
                    </div>
                )}
            </div>
        </h2>
    );
};