import { Button, Grid } from '@mui/material';
import { CourseSelectionProps, ScheduleWeek } from "manara-extension-types";

export default function CourseSelection(props: CourseSelectionProps) {
  function saveCourse(course: ScheduleWeek[]) {
    chrome.storage.local.set({ course: course });
    props.setCourse(course);
  }

  const buttons = props.courses && props.courses.currentScheduleWeek?.map((course) => (
    <Button
      style={{margin: "1rem"}}
      color="primary"
      variant="contained"
      fullWidth={true}
      onClick={() => saveCourse(course.modules)}
    >
      {course.name}
    </Button>
  ));

  return (
    <div
      style={{
        margin: "2rem 0rem",
        border: "solid 0.1rem lightgrey",
        borderRadius: "10px",
        padding: "1rem",
      }}
    >
        <Grid
          container
          alignItems="center"
          style={{
            padding: "1rem",
            textAlign: "center",
            justifyContent: "center",
          }}
        >
        <h1>
          Select Course
        </h1>
          {buttons}
      </Grid>
    </div>
  );
};
