import { Chip } from '@mui/material';

import { DifficultyChipProps } from 'manara-extension-types';

export default function DifficultyChip(props: DifficultyChipProps) {
    const { difficulty } = props;

    const getColor = (difficulty: string) => {
        switch (difficulty.toLowerCase()) {
            case "hard":
                return "error";
            case "medium":
                return "warning";
            case "easy":
                return "success";
            default:
                return "primary";
        }
    };

    return <Chip label={difficulty} color={getColor(difficulty)} />;
}